package com.circlenet.domain.circle.model;
import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="circle_post_reads") public class CirclePostReadEntity {@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="post_id",nullable=false)private Long postId;@Column(name="user_id",nullable=false)private Long userId;@Column(name="read_at",nullable=false)private Instant readAt=Instant.now();public Long getId(){return id;}public Long getPostId(){return postId;}public void setPostId(Long v){postId=v;}public Long getUserId(){return userId;}public void setUserId(Long v){userId=v;}public Instant getReadAt(){return readAt;}}
